contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: try to lock a guess with an arbitrary sent amount and observe whether it reverts.
    // The property: only sending exactly 1 ether should allow lockInGuess to succeed; any other amount must revert.
    function runTest(bytes32 hash, uint256 sendAmount) public payable {
        // ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // We perform the state-changing call as a top-level statement.
        // Capture whether it reverts by using a low-level call and storing the boolean result.
        (bool ok, ) = address(c).call{value: sendAmount}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));

        // The general rule: call succeeds iff sendAmount == 1 ether
        assert(ok == (sendAmount == 1 ether));
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // The rule: lockInGuess succeeds iff amount == 1 ether. Express as: not reverted <=> amount == 1 ether
        assert((!reverted) == (amount == 1 ether));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h, uint256 val1, uint256 val2) public payable {
        require(address(this).balance >= val1 + val2);
        bool r1; try c.lockInGuess{value: val1}(h) { r1 = false; } catch { r1 = true; }
        bool r2; try c.lockInGuess{value: val2}(h) { r2 = false; } catch { r2 = true; }
        // If a call with val1 succeeded and val1 == 1 ether, then any call with a different value must have reverted
        assert(!(r1 == false && val1 == 1 ether && val2 != val1 && r2 == false));
    }
    receive() external payable {}
}

contract InvMutTest {
