pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the sent amount; the deciding value is the sent amount
    function testFuzz_property(address actor, uint256 sendAmt) public {
        vm.assume(actor != address(0));
        // bound sendAmt broadly to a large range but include 1 ether and 2 ether
        uint256 amount = bound(sendAmt, 0, 5 ether);

        // prepare a hash guess value (can be any bytes32); keep deterministic from fuzz inputs
        bytes32 guess = bytes32(uint256(uint160(actor)) ^ amount);

        // fund actor so they can send
        vm.deal(actor, amount + 1 ether);

        // call lockInGuess as actor and catch whether it succeeded
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: amount}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property we assert (single assertion): if the call succeeded, then
        // the recorded block number for that actor's guess must be non-zero (i.e., state was set).
        // We read this through the contract's public behaviour by attempting to call settle later
        // depends on whether lockInGuess succeeded; but we can observe that a successful lockInGuess
        // implies the contract accepted the msg.value and set guesses[actor].block != 0.
        // To observe this purely via external surface, we assert that if call succeeded then the
        // subsequent call to lockInGuess by the same actor would revert because require(guesses[msg.sender].block == 0)
        // i.e., second lockInGuess must fail when first succeeded.

        // attempt a second lockInGuess from same actor with correct amount 1 ether (reference expects 1 ether)
        vm.prank(actor);
        bool secondOk;
        try c.lockInGuess{value: 1 ether}(guess) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Single assertion: if initial call succeeded then the second call must fail (so secondOk == false).
        // Reference: when initial succeeded it set guesses[actor].block != 0 preventing a second lock; mutant: differing acceptance may cause initial to fail while reference accepted or vice versa,
        // so fuzzing will find a sendAmt where reference accepted (ok==true) but mutant (which requires 2 ether) rejects; our assertion checks behavior that the reference must always satisfy.
        assertTrue(!ok || !secondOk);
    }
}

