pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzzed params: caller address and two distinct hashes to try to lock twice
    function testFuzz_property(address caller, bytes32 h1, bytes32 h2) public {
        // Keep caller a non-zero address and distinct hashes wide but allow equality too
        vm.assume(caller != address(0));

        // fund the caller so they can send 1 ether payments
        vm.deal(caller, 2 ether);

        // First lock-in by caller: should succeed on reference (and on mutant too)
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(h1);

        // Second lock-in by same caller: on reference this MUST revert (prevents overwrite),
        // so the call will fail; on mutant it will succeed (allow overwrite).
        bool ok;
        vm.prank(caller);
        try c.lockInGuess{value: 1 ether}(h2) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERT: reference always prevents a second successful lockInGuess by same caller,
        // so ok must be false for the reference; the mutant (which removed the require)
        // will allow ok==true for some inputs, so this assertion will fail on the mutant.
        assertTrue(!ok);
    }
}

