pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and the guess bytes32
    function testFuzz_property(address caller, bytes32 guess) public {
        // admissible domain: caller cannot be address(0) because vm.prank with address(0) is awkward
        vm.assume(caller != address(0));

        // fund the caller so they can send 1 ether
        vm.deal(caller, 2 ether);

        // record current block for comparison
        uint256 before = block.number;

        // perform lockInGuess from the fuzzed caller with exactly 1 ether
        vm.prank(caller);
        bool ok;
        // call and capture revert/success (per hard rules, use try/catch style via low-level call)
        // but since lockInGuess is non-payable? it's payable in contract; we use low-level call to detect success
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", guess));
        ok = success;

        // The general rule: for the reference contract, if lockInGuess succeeded, the stored block for caller is strictly > the block at which the call executed (i.e., > before)
        // Read the stored Guess.block via the auto getter: guesses is not public in original, but the contract defines mapping guesses; since it's not public, no getter exists.
        // However, we can observe behavior indirectly: the reference sets guess.block = block.number + 1, so that settling immediately in the same block should revert because require(block.number > guesses[msg.sender].block) will be false.
        // We'll attempt to call settle in the same block; for the reference this call should revert (i.e., fail) because stored block is > current, while in mutant (stored block == current) settle would allow success if answer matched (but more importantly the condition block.number > stored_block would be false in reference and also false in mutant if equal). To reliably distinguish, we instead check that the stored block is not equal to before by trying to re-lock: reference requires guesses[msg.sender].block == 0 to allow lockInGuess; but that doesn't help.

        // The simplest observable is: after successful lockInGuess, calling settle in the SAME block must revert (require(block.number > guesses[msg.sender].block)).
        // For reference: stored block = before + 1, so block.number (still before) > stored? false -> settle reverts.
        // For mutant: stored block = before, so block.number (before) > before? false -> settle also reverts. That doesn't distinguish.

        // Alternate observable: the reference sets stored block to before+1, so it is strictly > before. We can observe this by calling lockInGuess from caller and then calling lockInGuess again in the same block: the second call should revert because guesses[caller].block != 0 (it's set to nonzero). This holds for both reference and mutant, so not distinguishing.

        // We need a direct observation of stored block value. The original mapping 'guesses' is not public; however, the contract provides no getter. But the problem statement allows reading public getters only. To satisfy the requirement, we instead observe that the reference guarantees that after lockInGuess, the stored block is strictly greater than the block at call-time; we can test this by calling lockInGuess and then trying to call settle in the next block: for reference, advancing one block (to before+1) still does not satisfy block.number > stored_block (since stored_block == before+1 and block.number == before+1 -> not greater), so settle should still revert in the next block; for mutant, advancing one block (to before+1) makes block.number > stored_block true (before+1 > before), so settle may proceed (and in particular, settle will not revert on the block number check). Thus we can distinguish by advancing exactly one block and checking whether settle reverts due to the block.number > stored_block requirement.

        // proceed only if lockInGuess succeeded
        if (!ok) {
            // If lockInGuess reverted, then reference's preconditions (e.g., msg.value) weren't met; simply assert that the call did not succeed.
            // The single assertTrue below must still be used to state the general rule; in this branch we cannot observe further, so we'll assert that ok == ok (no-op) but per instructions must assert a property reading c. To keep universal, we restrict to cases where lockInGuess succeeded.
            return;
        }

        // advance exactly one block
        vm.roll(block.number + 1);

        // try settle from caller in the new block
        vm.prank(caller);
        (bool settleSuccess, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // For the reference contract: stored_block == before + 1, current block == before + 1, require(block.number > stored_block) fails => settle should revert => settleSuccess == false.
        // For the mutant: stored_block == before, current block == before + 1, require(block.number > stored_block) is true => settle may proceed => settleSuccess could be true (and funds possibly moved). Therefore the invariant we assert is that settle in the next block fails (is false).

        assertTrue(!settleSuccess);
    }
}
